-- SEAGAS — Skills Library v2
-- AUTO-GENERATED by data/skills/build_skills_seed.py — DO NOT EDIT BY HAND.
-- Edit data/skills/skills_library.csv, then run:
--     python data/skills/build_skills_seed.py
--     python -m pytest tests/test_skills_library.py -q
--     psql -U postgres -d seagas_db -f database/seed_skills_library_v2.sql
--
-- Total skills : 166  (AI_Digital 21, Analytical 20, Soft 16, Technical 109)
-- Generated at : 2026-10-29 13:17
--
-- Run AFTER schema.sql. Idempotent: ON CONFLICT (skill_name) DO UPDATE, so
-- alias / category / subcategory / description fixes to the 32 v1 skills
-- also take effect. Needs the subcategory and source columns, which
-- schema.sql (new databases) or migrate_existing_db.sql (older ones) add.
-- Any error aborts the whole transaction.
-- ============================================================

\set ON_ERROR_STOP on

BEGIN;

ON CONFLICT (skill_name) DO UPDATE SET
    category    = EXCLUDED.category,
    subcategory = EXCLUDED.subcategory,
    aliases     = EXCLUDED.aliases,
    description = EXCLUDED.description,
    source      = EXCLUDED.source;

COMMIT;

-- ── VERIFY ───────────────────────────────────────────────────
SELECT category, COUNT(*) AS skill_count
FROM skills_library
WHERE is_active = TRUE
GROUP BY category
ORDER BY category;
